<template>
  <view class="netops-page admin-page">
    <view class="admin-hero"><view><text>AIOPS CONTROL</text><strong>AIOps 系统管理</strong><small>模型、任务、运行参数与审计统一入口</small></view><view class="shield">控</view></view>
    <view v-if="error" class="notice">{{ error }}</view>
    <view class="overview-grid"><view><text>供应商</text><strong>{{ providers.length }}</strong></view><view><text>模型</text><strong>{{ models.length }}</strong></view><view><text>分析任务</text><strong>{{ tasks.length }}</strong></view><view><text>启用任务</text><strong>{{ enabledTasks }}</strong></view></view>
    <view class="tabs"><view v-for="item in tabs" :key="item.value" :class="{ active: tab === item.value }" @tap="tab = item.value">{{ item.label }}</view></view>

    <view v-if="loading" class="status-text">正在读取 AIOps 配置…</view>
    <template v-else-if="tab === 'models'">
      <view class="section-card"><view class="section-head"><view class="section-head-title">模型与供应商</view><view class="section-head-meta">{{ models.length }} 个模型</view></view><view class="card-list"><view v-for="item in providers" :key="item.id" class="data-card"><view class="card-title"><strong>{{ item.name || item.provider_name }}</strong><StatusBadge :value="item.enabled === false ? 'disabled' : (item.health_status || 'active')" /></view><text>{{ item.base_url || item.endpoint || '未配置服务地址' }}</text><view class="chip-row"><text v-for="model in providerModels(item.id)" :key="model.id">{{ model.name || model.model_name }}</text></view></view><EmptyState v-if="!providers.length" mark="模" title="暂无模型供应商" /></view></view>
    </template>
    <template v-else-if="tab === 'tasks'">
      <view class="section-card"><view class="section-head"><view class="section-head-title">分析任务</view><view class="section-head-meta">{{ tasks.length }} 项</view></view><view class="card-list"><view v-for="item in tasks" :key="item.id" class="data-card"><view class="card-title"><strong>{{ item.task_name || item.name || '未命名任务' }}</strong><StatusBadge :value="item.enabled ? 'active' : 'disabled'" /></view><text>{{ schedule(item) }} · 最近 {{ item.hours || 24 }} 小时</text><view class="task-meta"><view><small>上次执行</small><text>{{ time(item.last_run_at) }}</text></view><view><small>最近结果</small><text>{{ item.last_status || '尚未运行' }}</text></view></view><button class="run-button" :loading="runningId === item.id" @tap="runTask(item)">立即执行</button></view><EmptyState v-if="!tasks.length" mark="任" title="暂无分析任务" /></view></view>
    </template>
    <template v-else-if="tab === 'settings'">
      <view class="section-card"><view class="section-head"><view class="section-head-title">运行设置</view><view class="section-head-meta">只读概览</view></view><view class="setting-list"><view v-for="entry in settingEntries" :key="entry.key"><text>{{ entry.key }}</text><strong>{{ entry.value }}</strong></view></view></view>
    </template>
    <template v-else>
      <view class="section-card"><view class="section-head"><view class="section-head-title">最近操作日志</view><view class="section-head-meta">{{ logs.length }} 条</view></view><view class="log-list"><view v-for="(item,index) in logs" :key="item.id || index"><view><strong>{{ item.action || item.operation || '系统操作' }}</strong><StatusBadge :value="item.result || item.status || 'success'" /></view><text>{{ item.username || item.actor || item.user_name || '系统' }} · {{ time(item.created_at || item.occurred_at) }}</text><small>{{ item.detail || item.message || item.target || '' }}</small></view><EmptyState v-if="!logs.length" mark="志" title="暂无操作日志" /></view></view>
    </template>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import EmptyState from '../../../components/netops/EmptyState.vue'
import StatusBadge from '../../../components/netops/StatusBadge.vue'
import { getAiopsResource, sendAiopsResource } from '../../../api/aiops'
import { messageLabel } from '../../../utils/labels'

const tabs = [{ label: '模型', value: 'models' }, { label: '任务', value: 'tasks' }, { label: '设置', value: 'settings' }, { label: '日志', value: 'logs' }]
const tab = ref('models'); const providers = ref([]); const models = ref([]); const tasks = ref([]); const settings = ref({}); const logs = ref([]); const loading = ref(false); const error = ref(''); const runningId = ref(null)
const enabledTasks = computed(() => tasks.value.filter((item) => item.enabled).length)
const settingEntries = computed(() => Object.entries(settings.value || {}).filter(([, value]) => value !== null && value !== '' && typeof value !== 'object').map(([key, value]) => ({ key: settingLabel(key), value: typeof value === 'boolean' ? (value ? '开启' : '关闭') : String(value) })))
onLoad(load)
async function optional(path, fallback) { try { return await getAiopsResource(path) } catch (err) { if (!error.value) error.value = messageLabel(err.message); return fallback } }
async function load() { loading.value = true; error.value = ''; const providerData = await optional('/llm/providers', { items: [] }); const modelData = await optional('/llm/models', { items: [] }); const taskData = await optional('/report-tasks', { items: [] }); const settingData = await optional('/system/settings', { item: {} }); const logData = await optional('/system/operation-logs', { items: [] }); providers.value = providerData.items || []; models.value = modelData.items || []; tasks.value = taskData.items || []; settings.value = settingData.item || settingData || {}; logs.value = logData.items || []; loading.value = false }
function providerModels(id) { return models.value.filter((item) => String(item.provider_id) === String(id)).slice(0, 8) }
function schedule(item) { if (item.cron_expression) return item.cron_expression; if (item.interval_minutes) return `每 ${item.interval_minutes} 分钟`; return item.schedule || '按配置执行' }
function time(value) { if (!value) return '--'; const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? String(value) : `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}` }
function settingLabel(key) { return ({ analysis_hours: '默认分析窗口', refresh_minutes: '刷新间隔', timezone: '时区', task_enabled: '任务调度', qq_bot_enabled: 'QQ 机器人', max_findings: '最大研判数' })[key] || key }
async function runTask(item) { runningId.value = item.id; try { await sendAiopsResource(`/report-tasks/${item.id}/run-now`, 'POST', {}); uni.showToast({ title: '任务已触发', icon: 'success' }); await load() } catch (err) { uni.showToast({ title: messageLabel(err.message), icon: 'none' }) } finally { runningId.value = null } }
</script>

<style scoped>
.admin-page{padding-top:0}.admin-hero{display:flex;align-items:center;justify-content:space-between;margin:0 -24rpx 18rpx;padding:34rpx 30rpx;border-radius:0 0 28rpx 28rpx;background:linear-gradient(145deg,#142d4e,#285b91);color:#fff}.admin-hero text,.admin-hero strong,.admin-hero small{display:block}.admin-hero text{color:rgba(255,255,255,.52);font-size:17rpx;letter-spacing:2rpx}.admin-hero strong{margin-top:7rpx;font-size:33rpx}.admin-hero small{margin-top:7rpx;color:rgba(255,255,255,.68);font-size:19rpx}.shield{display:flex;width:68rpx;height:68rpx;align-items:center;justify-content:center;border:1rpx solid rgba(255,255,255,.25);border-radius:22rpx;background:rgba(255,255,255,.1);font-size:25rpx}.notice{margin-bottom:15rpx;padding:15rpx 18rpx;border-radius:12rpx;background:#fdebea;color:#b34540;font-size:21rpx}.overview-grid{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:16rpx;padding:16rpx 5rpx;border:1rpx solid #e1e7ee;border-radius:16rpx;background:#fff}.overview-grid view{text-align:center}.overview-grid text,.overview-grid strong{display:block}.overview-grid text{color:#8994a1;font-size:16rpx}.overview-grid strong{margin-top:4rpx;color:#285b91;font-size:27rpx}.tabs{display:flex;margin-bottom:17rpx;padding:6rpx;border-radius:14rpx;background:#e6ebf1}.tabs view{flex:1;padding:13rpx 5rpx;border-radius:10rpx;color:#68778a;font-size:20rpx;text-align:center}.tabs view.active{background:#fff;color:#245f9f;font-weight:700}.card-list{padding:0 21rpx 20rpx}.data-card{padding:19rpx 0;border-bottom:1rpx solid #edf1f5}.data-card:last-child{border:0}.card-title{display:flex;align-items:center;justify-content:space-between;gap:15rpx}.card-title strong{color:#2b3b4e;font-size:24rpx}.data-card>text{display:block;margin-top:8rpx;color:#83909f;font-size:19rpx}.chip-row{display:flex;flex-wrap:wrap;gap:7rpx;margin-top:11rpx}.chip-row text{padding:6rpx 10rpx;border-radius:8rpx;background:#eef3f8;color:#46637e;font-size:17rpx}.task-meta{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:13rpx}.task-meta view{padding:11rpx;border-radius:10rpx;background:#f5f7fa}.task-meta small,.task-meta text{display:block}.task-meta small{color:#929da9;font-size:16rpx}.task-meta text{margin-top:4rpx;color:#526176;font-size:18rpx}.run-button{display:flex;height:57rpx;margin-top:12rpx;align-items:center;justify-content:center;border:1rpx solid #cad9e8;border-radius:10rpx;background:#fff;color:#2862a0;font-size:19rpx}.setting-list{padding:3rpx 23rpx 17rpx}.setting-list view{display:flex;align-items:center;justify-content:space-between;gap:20rpx;padding:17rpx 0;border-bottom:1rpx solid #edf1f5}.setting-list text{color:#778493;font-size:20rpx}.setting-list strong{color:#35465a;font-size:20rpx;font-weight:600;text-align:right}.log-list{padding:0 22rpx 18rpx}.log-list>view{padding:18rpx 0;border-bottom:1rpx solid #edf1f5}.log-list>view>view{display:flex;justify-content:space-between}.log-list strong{color:#334458;font-size:22rpx}.log-list text,.log-list small{display:block;margin-top:6rpx;color:#8792a0;font-size:18rpx}.log-list small{color:#606f81;line-height:1.5}
</style>
